-- Demo restaurant: cover photo (app/public/demo/lindehof-cover.jpg, AI-generated by the owner),
-- copied into the branding bucket by the edge function seed-demo-branding. The top of the menu
-- switches from the coloured band to the cover photo.
update public.restaurants
set theme = theme || jsonb_build_object('cover_path', id::text || '/lindehof-cover.jpg', 'header', 'cover')
where slug = 'demo';
